<?php
declare(strict_types=1);
namespace EPejabat\Modules\Training;
use EPejabat\Core\{Database,Core,Audit,Pdf};
final class Reporting {
 public static function rows(\PDO $p,int $u,int $programme,array $filters=[]):array {ExtendedMigrations::require($p);$r=Policy::programme($p,$programme);Policy::require($p,$u,'reports.view',$r);$c=Policy::config($p,$r,true);$rows=[];foreach(Database::query($p,'SELECT r.*,a.status AS acknowledgement FROM training_registrations r LEFT JOIN training_acknowledgements a ON a.registration_id=r.id WHERE r.programme_id=? ORDER BY r.id',[$programme])->fetchAll() as $reg){$s=json_decode($reg['snapshot_json'],true);$roles=Database::query($p,'SELECT pr.code FROM training_participation_assignments a JOIN training_participation_roles pr ON pr.id=a.role_id WHERE a.registration_id=?',[$reg['id']])->fetchAll(\PDO::FETCH_COLUMN);$sessions=[];if($reg['status']==='CONFIRMED')foreach(Database::query($p,'SELECT id FROM training_sessions WHERE programme_id=?',[$programme])->fetchAll() as $session)$sessions[]=Attendance::status($p,$u,(int)$session['id'],(int)$reg['id']);$points=Database::query($p,"SELECT points FROM training_cpd_records WHERE registration_id=? AND status='APPROVED' ORDER BY id DESC LIMIT 1",[$reg['id']])->fetchColumn();$certs=(int)Database::query($p,"SELECT COUNT(*) FROM training_outputs WHERE registration_id=? AND kind='CERTIFICATE' AND status='LOCKED'",[$reg['id']])->fetchColumn();$row=['registration'=>$reg['id'],'programme'=>$c['title'],'year'=>substr($c['start_at'],0,4),'name'=>$s['full_name'],'organisation'=>$s['organisation_name'],'organisation_id'=>$s['organisation_id'],'facility_id'=>$s['facility_id'],'unit_id'=>$s['unit_id'],'profession_id'=>$s['profession_id'],'position_id'=>$s['position_id'],'grade_id'=>$s['grade_id'],'role'=>implode(',',$roles),'registration_status'=>$reg['status'],'source'=>$reg['source'],'acknowledgement'=>$reg['acknowledgement']??'PENDING','attendance'=> $sessions&&!array_filter($sessions,fn($x)=>!$x['completed'])?'ATTENDANCE_COMPLETED':($sessions?implode(',',array_unique(array_column($sessions,'status'))):'ABSENT'),'arrival'=>implode(',',array_unique(array_column($sessions,'arrival'))),'cpd_points'=>$points===false?'':$points,'certificates'=>$certs];$match=true;foreach($filters as $key=>$value){if(!array_key_exists($key,$row))throw new \RuntimeException('Filter tidak sah.');if((string)$value!==''&&($key==='role'?!in_array((string)$value,$roles,true):(string)$row[$key]!== (string)$value))$match=false;}if($match)$rows[]=$row;}return $rows;}
 public static function dashboard(\PDO $p,int $u,int $programme):array {$rows=self::rows($p,$u,$programme);$summary=['registered'=>count($rows),'confirmed'=>0,'declined'=>0,'pending'=>0,'walk_in'=>0,'attendance_completed'=>0,'cpd_points'=>0,'certificates'=>0,'on_time'=>0,'late'=>0,'too_late'=>0,'absent'=>0];foreach($rows as $r){$summary['confirmed']+=(int)($r['registration_status']==='CONFIRMED');$summary['declined']+=(int)($r['acknowledgement']==='DECLINED');$summary['pending']+=(int)($r['registration_status']==='PENDING');$summary['walk_in']+=(int)($r['source']==='WALK_IN');$summary['attendance_completed']+=(int)($r['attendance']==='ATTENDANCE_COMPLETED');$summary['cpd_points']+=(float)$r['cpd_points'];$summary['certificates']+=$r['certificates'];foreach(['on_time'=>'ON_TIME','late'=>'LATE','too_late'=>'TOO_LATE','absent'=>'ABSENT'] as $key=>$value)$summary[$key]+=(int)($r['registration_status']==='CONFIRMED'&&in_array($value,explode(',',$r['arrival']?:'ABSENT'),true));}$summary['assigned']=(int)Database::query($p,"SELECT COUNT(*) FROM training_registrations WHERE programme_id=? AND assigned_by IS NOT NULL",[$programme])->fetchColumn();$summary['events']=Database::query($p,'SELECT e.action,COUNT(*) AS total FROM training_attendance_events e JOIN training_sessions s ON s.id=e.session_id WHERE s.programme_id=? GROUP BY e.action',[$programme])->fetchAll();return $summary;}
 private static function safe(mixed $v):string {$s=(string)$v;return preg_match('/^[=+\-@\t\r]/',ltrim($s))?"'".$s:$s;}
 public static function export(\PDO $p,int $u,int $programme,string $format,array $filters=[]):string {$r=Policy::programme($p,$programme);Policy::require($p,$u,'reports.export',$r);$rows=self::rows($p,$u,$programme,$filters);$head=$rows?array_keys($rows[0]):['registration','programme','name'];$table=[$head];foreach($rows as $row)$table[]=array_map([self::class,'safe'],array_values($row));$bytes=match($format){'CSV'=>self::csv($table),'PDF'=>Pdf::generate(array_map(fn($row)=>implode(' | ',$row),$table)),'XLSX'=>self::xlsx($table),default=>throw new \RuntimeException('CSV/PDF/XLSX sahaja.')};Audit::record($p,'report.exported',$u,(int)$r['owner_organisation_id'],(string)$programme,'training',null,null,['format'=>$format,'rows'=>count($rows),'filters'=>$filters]);return $bytes;}
 private static function csv(array $rows):string {$f=fopen('php://temp','w+');foreach($rows as $row)fputcsv($f,$row);rewind($f);$bytes=stream_get_contents($f);fclose($f);return $bytes;}
 private static function xlsx(array $rows):string {$f=tempnam(sys_get_temp_dir(),'epxlsx');$z=new \ZipArchive();if($z->open($f,\ZipArchive::OVERWRITE)!==true)throw new \RuntimeException('Export tidak tersedia.');try{$z->addFromString('[Content_Types].xml','<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>');$z->addFromString('_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');$z->addFromString('xl/workbook.xml','<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Training" sheetId="1" r:id="rId1"/></sheets></workbook>');$z->addFromString('xl/_rels/workbook.xml.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>');$xml='<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>';foreach($rows as $i=>$row){$xml.='<row r="'.($i+1).'">';foreach($row as $j=>$value){$col='';for($n=$j+1;$n>0;$n=intdiv($n-1,26))$col=chr(65+($n-1)%26).$col;$xml.='<c r="'.$col.($i+1).'" t="inlineStr"><is><t xml:space="preserve">'.htmlspecialchars((string)$value,ENT_XML1|ENT_QUOTES,'UTF-8').'</t></is></c>';}$xml.='</row>';}$xml.='</sheetData></worksheet>';$z->addFromString('xl/worksheets/sheet1.xml',$xml);$z->close();return file_get_contents($f);}finally{if(is_file($f))unlink($f);}}
 public static function mine(\PDO $p,int $u,array $filters=[]):array {ExtendedMigrations::require($p);$a=Policy::actor($p,$u);$rows=[];foreach(Database::query($p,'SELECT * FROM training_registrations WHERE staff_identity_id=? ORDER BY id DESC',[$a['staff_identity_id']])->fetchAll() as $reg){$r=Policy::programme($p,(int)$reg['programme_id']);$c=Policy::config($p,$r,true);$roles=Database::query($p,'SELECT pr.code FROM training_participation_assignments pa JOIN training_participation_roles pr ON pr.id=pa.role_id WHERE pa.registration_id=?',[$reg['id']])->fetchAll(\PDO::FETCH_COLUMN);$outputs=Database::query($p,"SELECT id,kind,role_key,status,document_id,verification_key FROM training_outputs WHERE registration_id=? AND status IN ('LOCKED','VOID')",[$reg['id']])->fetchAll();$cpd=Database::query($p,"SELECT id,points,status,breakdown_json FROM training_cpd_records WHERE registration_id=? ORDER BY id DESC",[$reg['id']])->fetchAll();$item=['registration'=>$reg['id'],'programme_id'=>$r['id'],'programme'=>$c['title'],'year'=>substr($c['start_at'],0,4),'type'=>$c['type'],'organiser'=>$c['organiser'],'roles'=>$roles,'registration_status'=>$reg['status'],'historical_profile'=>json_decode($reg['snapshot_json'],true),'cpd'=>$cpd,'documents'=>$outputs];$match=true;foreach($filters as $k=>$v){if(!in_array($k,['year','type','role','organiser'],true))throw new \RuntimeException('Filter tidak sah.');if($v!==''&&($k==='role'?!in_array($v,$roles,true):$item[$k]!==$v))$match=false;}if($match)$rows[]=$item;}return $rows;}
}
